mkdir -p "\$HOME/.local/share/ccleste"
export CCLESTE_INPUT_CFG_PATH="\$HOME/.local/share/ccleste/input-cfg.txt"
cd "$PREFIX/lib/copal-store/ccleste" && exec ./ccleste "\$@"
