    mkdir -p "$DEST$PREFIX/bin" "$DEST$PREFIX/share/oh-my-posh"
    (cd "$_s/src" && GOPATH="$W/go" GOCACHE="$W/gocache" GOFLAGS=-modcacherw CGO_ENABLED=0 \
        go build -trimpath -o "$DEST$PREFIX/bin/oh-my-posh" \
